-- =====================================================================
-- Session 499b migration — 2026-11-13
-- KJV New Testament Greek-form names -> the Old Testament King James
-- spellings, so one man carries one name across both testaments
-- (Elias -> Elijah, Esaias -> Isaiah, Booz -> Boaz, Sion -> Zion ...).
-- Yoshi's call, Nov 13 2026, following S499 (Noe -> Noah).
--
-- Scope: verses of the 27 New Testament books in every edition that has
-- them, plus the card surfaces that quote them (commentary bodies, xref
-- notes, thread summaries, member notes). Word-boundary regex per name;
-- the card surfaces are swept whole because these spellings occur only
-- as quotations of these verses.
-- Verse-scoped by hand where one spelling names two men:
--   Judas -> Judah only at Matthew 1:2-3 (the patriarch); Iscariot, the
--     brother, Barsabas, the Galilean keep their name.
--   Juda -> Judah everywhere except Mark 6:3 (Jude, the brother).
--   Zacharias -> Zechariah only at Matthew 23:35 / Luke 11:51 (the
--     prophet); the Immerser's father keeps Zacharias.
--   Acts 7:45 and Hebrews 4:8: 'Yahusha (Jesus)' -> 'Joshua' — the verse
--     names the son of Nun, not the Messiah (the pipeline restored it as
--     if it were).
-- Left alone on purpose: Elisabeth (NT era), Enos, Cainan (the OT KJV
-- spells them the same), Aram, Joram (ambiguous).
-- Rule 10: UPDATE in place, ids and verse numbers untouched. Idempotent.
-- Run:  python3 api/apply_migration.py data-schema/migrations/session499b_nt_greek_names.sql
-- =====================================================================
\echo 'session499b — NT Greek-form names starting...'
BEGIN;

CREATE TEMP TABLE _nt ON COMMIT DROP AS SELECT v.id FROM verses v JOIN chapters c ON c.id=v.chapter_id JOIN books b ON b.id=c.book_id WHERE b.slug IN ('matthew','mark','luke','john','acts','romans','1-corinthians','2-corinthians','galatians','ephesians','philippians','colossians','1-thessalonians','2-thessalonians','1-timothy','2-timothy','titus','philemon','hebrews','james','1-peter','2-peter','1-john','2-john','3-john','jude','revelation');
DO $before$ DECLARE n INT; m INT; BEGIN SELECT count(*) INTO n FROM _nt; SELECT count(*) INTO m FROM verses WHERE id IN (SELECT id FROM _nt) AND text ~ '\m(Elias|Esaias|Jonas|Booz|Sion|Juda|Gomorrha|Sara)\M'; RAISE NOTICE 'S499b BEFORE  NT verse rows in scope: %  (a sample of the names still present in: % verses)', n, m; END $before$;
UPDATE verses SET text = regexp_replace(text, '\mElias\M', 'Elijah', 'g') WHERE id IN (SELECT id FROM _nt) AND text ~ '\mElias\M';
UPDATE commentary_entries SET body = regexp_replace(body, '\mElias\M', 'Elijah', 'g') WHERE body ~ '\mElias\M';
UPDATE cross_references SET note = regexp_replace(note, '\mElias\M', 'Elijah', 'g') WHERE note ~ '\mElias\M';
UPDATE cross_reference_threads SET summary_md = regexp_replace(summary_md, '\mElias\M', 'Elijah', 'g') WHERE summary_md ~ '\mElias\M';
UPDATE cross_reference_thread_members SET member_note = regexp_replace(member_note, '\mElias\M', 'Elijah', 'g') WHERE member_note ~ '\mElias\M';
