DO $after$ DECLARE n INT; j INT; BEGIN
  SELECT count(*) INTO n FROM verses WHERE id IN (SELECT id FROM _nt) AND text ~ '\m(Elias|Esaias|Jeremias|Jeremy|Jonas|Osee|Booz|Rachab|Urias|Roboam|Ozias|Ezekias|Manasses|Josias|Zorobabel|Gomorrha|Sion|Sara|Agar|Chanaan|Sem|Thamar|Phares)\M';
  SELECT count(*) INTO j FROM verses WHERE id IN (SELECT id FROM _nt) AND text ~ '\mJoshua\M';
  RAISE NOTICE 'S499b AFTER  NT verses still carrying a listed Greek-form name: % (expect 0); NT verses saying Joshua: % (expect 2)', n, j;
END $after$;
COMMIT;
